import json
from pathlib import Path
question='What document type or SEC form is this (e.g. 10-K, 10-Q, 8-K, earnings release, annual report)?'
sample=json.loads(Path('data/financebench/sample/single_cluster/random/sample_doc_labels.json').read_text())
cache_path=Path('data/financebench/stats/new_query_labels_cache.json')
cache=json.loads(cache_path.read_text())
fixed={}
for doc in sample:
    if doc in cache and question in cache[doc]:
        fixed[doc]=cache[doc][question]
    else:
        name=doc[:-4].upper()
        if '_10K' in name:
            fixed[doc]='Form 10-K'
        elif '_10Q' in name:
            fixed[doc]='Form 10-Q'
        elif '_8K' in name:
            fixed[doc]='Form 8-K'
        else:
            fixed[doc]=None
print(json.dumps(fixed, indent=2))
print('n_none', sum(v is None for v in fixed.values()))
PY"

